class Solution {
public:
    double trimMean(vector<int>& arr) {
        sort(arr.begin(), arr.end());
        int n = arr.size(), k = n / 20;
        long long sum = 0;
        for (int i = k; i < n - k; ++i) sum += arr[i];
        return (double)sum / (n - 2 * k);
    }
};

