class Solution:
    def trimMean(self, arr: List[int]) -> float:
        V = 100001
        cnt = [0] * V
        for x in arr:
            cnt[x] += 1
        n, k = len(arr), len(arr) // 20
        total = 0
        rem = k
        for v in range(V):
            t = min(rem, cnt[v])
            rem -= t
            total += (cnt[v] - t) * v
        rem = k
        for v in range(V - 1, -1, -1):
            if rem == 0:
                break
            t = min(rem, cnt[v])
            rem -= t
            total -= t * v
        return total / (n - 2 * k)

