class Solution {
public:
    double trimMean(vector<int>& arr) {
        const int V = 100001;
        vector<int> cnt(V, 0);
        for (int x : arr) cnt[x]++;
        int n = arr.size(), k = n / 20;
        long long total = 0;
        int rem = k;
        for (int v = 0; v < V; ++v) {
            int t = min(rem, cnt[v]);
            rem -= t;
            total += (long long)(cnt[v] - t) * v;
        }
        rem = k;
        for (int v = V - 1; v >= 0 && rem > 0; --v) {
            int t = min(rem, cnt[v]);
            rem -= t;
            total -= (long long)t * v;
        }
        return (double)total / (n - 2LL * k);
    }
};

