        for (int x : arr) cnt[x]++;
        int n = arr.length, k = n / 20;
        long total = 0;
        int rem = k;
        for (int v = 0; v < V; v++) {
            int t = Math.min(rem, cnt[v]);
            rem -= t;
            total += (long) (cnt[v] - t) * v;
        }
        rem = k;
        for (int v = V - 1; v >= 0 && rem > 0; v--) {
            int t = Math.min(rem, cnt[v]);
            rem -= t;
            total -= (long) t * v;
        }
        return (double) total / (n - 2L * k);
    }
}

